<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Conway's Game of Life</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }

  html, body {
    height: 100%;
    background: #0b0e14;
    color: #e6e9f0;
    font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  }

  body {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 18px;
    padding: 24px;
    min-height: 100vh;
  }

  h1 {
    font-size: 1.6rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    background: linear-gradient(90deg, #5eead4, #818cf8, #f472b6);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    text-shadow: none;
  }

  #stage {
    position: relative;
    padding: 14px;
    border-radius: 16px;
    background: #11151f;
    box-shadow:
      0 0 0 1px #232a3a,
      0 12px 40px rgba(0, 0, 0, 0.6),
      0 0 60px rgba(94, 234, 212, 0.05);
  }

  #life {
    display: block;
    width: 600px;
    height: 600px;
    border-radius: 8px;
    background: #0b0e14;
    cursor: crosshair;
    touch-action: none;
  }

  #hud {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 628px;
    font-size: 0.85rem;
    color: #8b93a7;
    font-variant-numeric: tabular-nums;
  }

  #hud span b { color: #5eead4; font-weight: 600; }

  #controls {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    justify-content: center;
  }

  button {
    font: inherit;
    font-size: 0.95rem;
    font-weight: 600;
    padding: 10px 20px;
    border: none;
    border-radius: 999px;
    cursor: pointer;
    color: #0b0e14;
    background: #5eead4;
    transition: transform 0.12s ease, box-shadow 0.12s ease, background 0.2s ease;
    box-shadow: 0 4px 14px rgba(94, 234, 212, 0.25);
    user-select: none;
  }

  button:hover { transform: translateY(-2px) scale(1.04); box-shadow: 0 6px 20px rgba(94, 234, 212, 0.4); }
  button:active { transform: translateY(0) scale(0.96); }

  #play   { background: #818cf8; box-shadow: 0 4px 14px rgba(129, 140, 248, 0.3); }
  #play:hover { box-shadow: 0 6px 20px rgba(129, 140, 248, 0.45); }
  #play.running { background: #f472b6; box-shadow: 0 4px 14px rgba(244, 114, 182, 0.35); }

  #random { background: #facc15; box-shadow: 0 4px 14px rgba(250, 204, 21, 0.25); }
  #random:hover { box-shadow: 0 6px 20px rgba(250, 204, 21, 0.4); }

  #clear  { background: #f87171; box-shadow: 0 4px 14px rgba(248, 113, 113, 0.25); }
  #clear:hover { box-shadow: 0 6px 20px rgba(248, 113, 113, 0.4); }

  #speed {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.8rem;
    color: #8b93a7;
  }

  #speed input {
    accent-color: #5eead4;
    cursor: pointer;
    width: 110px;
  }

  .hint {
    font-size: 0.78rem;
    color: #5a6378;
  }
</style>
</head>
<body>

  <h1>&#10022; Conway's Game of Life &#10022;</h1>

  <div id="hud">
    <span>Generation <b id="gen">0</b></span>
    <span>Population <b id="pop">0</b></span>
  </div>

  <div id="stage">
    <canvas id="life" width="600" height="600"></canvas>
  </div>

  <div id="controls">
    <button id="step"  title="Advance one generation">&#9197; Step</button>
    <button id="play"  title="Toggle auto-run">&#9654; Play</button>
    <button id="random" title="Seed random cells">&#127922; Random</button>
    <button id="clear" title="Kill all cells">&#128165; Clear</button>
    <label id="speed">&#9201;
      <input id="rate" type="range" min="1" max="30" value="10">
      <span id="rateLabel">10/s</span>
    </label>
  </div>

  <p class="hint">Click or drag on the grid to paint cells &mdash; B3/S23, edges are dead.</p>

<script>
(function () {
  "use strict";

  /* ---------- Grid state ---------- */
  var COLS = 50, ROWS = 50;            // >= 40 x 40 as required
  var CELL = 12;                       // CSS pixels per cell -> 600 x 600 canvas
  var grid  = new Uint8Array(COLS * ROWS);
  var next  = new Uint8Array(COLS * ROWS);
  var generation = 0;

  var canvas = document.getElementById("life");
  var ctx = canvas.getContext("2d");

  // Crisp rendering on high-DPI screens while keeping 600x600 CSS pixels.
  var dpr = Math.max(1, window.devicePixelRatio || 1);
  canvas.width  = COLS * CELL * dpr;
  canvas.height = ROWS * CELL * dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  var genEl = document.getElementById("gen");
  var popEl = document.getElementById("pop");

  function idx(x, y) { return y * COLS + x; }
  function inBounds(x, y) { return x >= 0 && x < COLS && y >= 0 && y < ROWS; }

  function get(x, y) {
    if (!inBounds(x, y)) return 0;
    return grid[idx(x, y)];
  }

  function set(x, y, v) {
    if (!inBounds(x, y)) return;
    grid[idx(x, y)] = v ? 1 : 0;
    draw();
  }

  /* ---------- Simulation: strict B3/S23, dead edges, simultaneous update ---------- */
  function step() {
    for (var y = 0; y < ROWS; y++) {
      for (var x = 0; x < COLS; x++) {
        var n = 0;
        // Count the 8 neighbours; out-of-bounds reads return 0 (dead edges).
        for (var dy = -1; dy <= 1; dy++) {
          for (var dx = -1; dx <= 1; dx++) {
            if (dx === 0 && dy === 0) continue;
            var nx = x + dx, ny = y + dy;
            if (nx >= 0 && nx < COLS && ny >= 0 && ny < ROWS) {
              n += grid[idx(nx, ny)];
            }
          }
        }
        var alive = grid[idx(x, y)];
        // Birth on exactly 3; survival on 2 or 3; death otherwise.
        next[idx(x, y)] = (alive ? (n === 2 || n === 3) : (n === 3)) ? 1 : 0;
      }
    }
    // Apply all at once (swap buffers) so the generation is truly simultaneous.
    var tmp = grid; grid = next; next = tmp;
    generation++;
    draw();
  }

  function clear() {
    grid.fill(0);
    generation = 0;
    draw();
  }

  function randomize() {
    for (var i = 0; i < grid.length; i++) {
      grid[i] = Math.random() < 0.25 ? 1 : 0;
    }
    generation = 0;
    draw();
  }

  /* ---------- Rendering ---------- */
  function draw() {
    var W = COLS * CELL, H = ROWS * CELL;

    ctx.fillStyle = "#0b0e14";
    ctx.fillRect(0, 0, W, H);

    // Subtle grid lines.
    ctx.strokeStyle = "rgba(120, 135, 170, 0.10)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (var x = 0; x <= COLS; x++) {
      ctx.moveTo(x * CELL + 0.5, 0);
      ctx.lineTo(x * CELL + 0.5, H);
    }
    for (var y = 0; y <= ROWS; y++) {
      ctx.moveTo(0, y * CELL + 0.5);
      ctx.lineTo(W, y * CELL + 0.5);
    }
    ctx.stroke();

    // Live cells: glowing rounded dots whose hue drifts with the generation.
    var hue = (160 + generation * 3) % 360;
    var pop = 0;
    ctx.fillStyle = "hsl(" + hue + ", 85%, 62%)";
    ctx.shadowColor = "hsl(" + hue + ", 90%, 60%)";
    ctx.shadowBlur = 8;

    var pad = 1.5, r = (CELL - pad * 2) / 2;
    for (var cy = 0; cy < ROWS; cy++) {
      for (var cx = 0; cx < COLS; cx++) {
        if (grid[idx(cx, cy)]) {
          pop++;
          var px = cx * CELL + CELL / 2;
          var py = cy * CELL + CELL / 2;
          ctx.beginPath();
          ctx.arc(px, py, r, 0, Math.PI * 2);
          ctx.fill();
        }
      }
    }
    ctx.shadowBlur = 0;

    genEl.textContent = generation;
    popEl.textContent = pop;
  }

  /* ---------- Painting with mouse / touch ---------- */
  var painting = false;
  var paintValue = 1;

  function cellFromEvent(e) {
    var rect = canvas.getBoundingClientRect();
    var x = Math.floor((e.clientX - rect.left) / rect.width  * COLS);
    var y = Math.floor((e.clientY - rect.top)  / rect.height * ROWS);
    return { x: x, y: y };
  }

  canvas.addEventListener("pointerdown", function (e) {
    e.preventDefault();
    var c = cellFromEvent(e);
    if (!inBounds(c.x, c.y)) return;
    // First click toggles; dragging then paints that same state.
    paintValue = get(c.x, c.y) ? 0 : 1;
    set(c.x, c.y, paintValue);
    painting = true;
    canvas.setPointerCapture(e.pointerId);
  });

  canvas.addEventListener("pointermove", function (e) {
    if (!painting) return;
    var c = cellFromEvent(e);
    if (inBounds(c.x, c.y)) set(c.x, c.y, paintValue);
  });

  function stopPainting() { painting = false; }
  canvas.addEventListener("pointerup", stopPainting);
  canvas.addEventListener("pointercancel", stopPainting);

  /* ---------- Controls ---------- */
  var running = false;
  var timer = null;
  var rateInput = document.getElementById("rate");
  var rateLabel = document.getElementById("rateLabel");
  var playBtn = document.getElementById("play");

  function startRun() {
    if (running) return;
    running = true;
    playBtn.innerHTML = "&#10074;&#10074; Pause";
    playBtn.classList.add("running");
    schedule();
  }

  function stopRun() {
    running = false;
    if (timer) { clearTimeout(timer); timer = null; }
    playBtn.innerHTML = "&#9654; Play";
    playBtn.classList.remove("running");
  }

  function schedule() {
    if (!running) return;
    timer = setTimeout(function () {
      step();
      schedule();
    }, 1000 / (+rateInput.value));
  }

  playBtn.addEventListener("click", function () {
    running ? stopRun() : startRun();
  });

  document.getElementById("step").addEventListener("click", function () {
    stopRun();
    step();
  });

  document.getElementById("random").addEventListener("click", function () {
    randomize();
  });

  document.getElementById("clear").addEventListener("click", function () {
    stopRun();
    clear();
  });

  rateInput.addEventListener("input", function () {
    rateLabel.textContent = rateInput.value + "/s";
  });

  // Spacebar toggles play for extra fun.
  window.addEventListener("keydown", function (e) {
    if (e.code === "Space" && e.target === document.body) {
      e.preventDefault();
      running ? stopRun() : startRun();
    }
  });

  /* ---------- Programmatic API (grading contract) ---------- */
  window.life = {
    w: COLS,
    h: ROWS,
    get: get,
    set: set,
    step: step,
    clear: clear
  };

  /* ---------- Seed something fun & go ---------- */
  randomize();
  startRun();
})();
</script>
</body>
</html>
